function decodeEntities(value) {
  const named = { amp: '&', apos: "'", gt: '>', lt: '<', nbsp: ' ', quot: '"' };
  return value.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (entity, reference) => {
    const lower = reference.toLowerCase();
    if (lower[0] !== '#') return named[lower] ?? entity;
    const codePoint = lower.startsWith('#x') ? Number.parseInt(lower.slice(2), 16) : Number.parseInt(lower.slice(1), 10);
    try { return String.fromCodePoint(codePoint); } catch { return entity; }
  });
}

const html = String($input.first().json.product_html ?? '');
const latest = /<div\b(?=[^>]*\bclass\s*=\s*(["'])[^"']*\bfirmware-latest\b[^"']*\1)(?=[^>]*\bdata-title\s*=\s*(["'])(.*?)\2)[^>]*>/i.exec(html);
if (!latest) throw new Error('NETGEAR product page did not contain .firmware-latest with a data-title attribute.');

const title = decodeEntities(latest[3]).trim();
const section = html.slice(latest.index, latest.index + 12000);
const releaseNotes = /<a\b[^>]*\bhref\s*=\s*(["'])(.*?)\1[^>]*>\s*Release\s*Notes\s*<\/a>/i.exec(section);
if (!title || !releaseNotes) throw new Error('NETGEAR latest firmware entry did not include both its title and Release Notes link.');

const releaseUrl = decodeEntities(releaseNotes[2]).trim();
if (!/^https:\/\//i.test(releaseUrl)) throw new Error(`NETGEAR returned a non-HTTPS release-notes URL: ${releaseUrl}`);

return [{ json: { firmware_title: title, release_url: releaseUrl } }];

function decodeEntities(value) {
  const named = { amp: '&', apos: "'", gt: '>', lt: '<', nbsp: ' ', quot: '"' };
  return value.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (entity, reference) => {
    const lower = reference.toLowerCase();
    if (lower[0] !== '#') return named[lower] ?? entity;
    const codePoint = lower.startsWith('#x') ? Number.parseInt(lower.slice(2), 16) : Number.parseInt(lower.slice(1), 10);
    try { return String.fromCodePoint(codePoint); } catch { return entity; }
  });
}

function htmlToText(value) {
  return decodeEntities(value.replace(/<br\s*\/?\s*>/gi, '\n').replace(/<[^>]+>/g, '')).replace(/\s+/g, ' ').trim();
}

function escapeMarkdown(value) {
  return value.replace(/([\\`*_{}[\]<>])/g, '\\$1');
}

const source = $('Find latest RBR20 firmware').item.json;
const html = String($input.first().json.release_notes_html ?? '');
const title = htmlToText(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i.exec(html)?.[1] ?? source.firmware_title);
const date = htmlToText(/Release\s*Date:\s*<\/strong>\s*<br\s*\/?\s*>\s*([^<]+)/i.exec(html)?.[1] ?? '');
if (!date) throw new Error('NETGEAR release notes did not contain a Release Date.');

const version = /(?:firmware\s+)?version\s+v?([0-9]+(?:\.[0-9]+)+)/i.exec(title)?.[1] ?? source.firmware_title;
const releaseId = `${version}|${source.release_url}`;
return [{
  json: {
    release_id: releaseId,
    title,
    release_date: date,
    release_url: source.release_url,
    first_seen_at: new Date().toISOString(),
    message: [
      `📡 **NETGEAR Orbi RBR20 firmware: ${escapeMarkdown(title)}**`,
      '',
      `Release date: ${escapeMarkdown(date)}`,
      '',
      `[View the release notes](${source.release_url})`,
    ].join('\n'),
    matrix_request_id: `netgear-rbr20-firmware-${encodeURIComponent(releaseId)}`,
  },
}];

const firmware = $('Prepare RBR20 firmware alert').item.json;

return {
  json: {
    release_id: firmware.release_id,
    title: firmware.title,
    release_date: firmware.release_date,
    release_url: firmware.release_url,
    first_seen_at: firmware.first_seen_at,
    matrix_event_id: $json.event_id ?? null,
  },
};
